/**
 * What the delay rail needs to know about a command, as DATA: a client asks
 * this table rather than carrying a list of ids it recognises.
 */
export interface GeneratedCommandRail {
  /** Whether the dispatch resolves with anything, i.e. whether an ack comes back. */
  readonly replies: boolean;
  /**
   * Whether the host holds this command for the signal delay before running it,
   * off the same `[SitrepCommand(Delayed = ...)]` the host itself dispatches by.
   */
  readonly delayed: boolean;
  /**
   * The args field holding the UT this command acts at, off
   * `[SitrepCommand(ArriveBefore = ...)]`. A client refuses to send the command
   * when it would reach the craft at or after that UT. Absent for every other
   * command.
   */
  readonly arriveBefore?: string;
}

/**
 * The rail columns for every command above, keyed the same way.
 *
 * An Uplink's own commands come out of ITS map, and its client feeds them to
 * the SDK through `registerUplinkCommand`.
 *
 * `replies` reads `true` on every row here, and that is a finding rather than
 * a placeholder: `Sitrep.Contract/CommandResult.cs` rules that results are
 * always delivered, never a fire-and-forget void, so no declared command can
 * be unacked. The column exists because a client must READ that rather than
 * assume it; the day the contract declares a command that answers nothing,
 * this is where it says so.
 *
 * `delayed` is the mod's own dispatch decision, not a client-side opinion of
 * it. A `false` row runs the instant it arrives, so drawing it a countdown or
 * an in-flight queue entry would be a fiction about the operator's own order.
 */
